package com.sakan.iptv;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.nio.charset.StandardCharsets;
public class ProviderFeaturesTest {
 private ProviderTest fixture;private List<String> queries;
 @Before public void start()throws Exception{fixture=new ProviderTest();fixture.setup();queries=Collections.synchronizedList(new ArrayList<>());fixture.server.createContext("/",e->{String q=e.getRequestURI().getRawQuery();queries.add(q==null?"":q);long now=System.currentTimeMillis()/1000;String result="{}";try{JSONObject row=new JSONObject().put("id",88).put("title","TmV3cw==").put("start_timestamp",now-7200).put("stop_timestamp",now-3600).put("has_archive",1).put("mark_archive",1);if(q.contains("action=handshake"))result="{\"js\":{\"token\":\"mock\"}}";else if(q.contains("action=get_profile"))result="{\"js\":{\"blocked\":0}}";else if(q.contains("action=get_simple_data_table")){JSONObject data=new JSONObject().put("data",new JSONArray().put(row)).put("total_items",1);result=q.contains("type=epg")?new JSONObject().put("js",data).toString():new JSONObject().put("epg_listings",new JSONArray().put(row)).toString();}else if(q.contains("type=tv_archive"))result="{\"js\":{\"cmd\":\"ffmpeg https://cdn.example.test/archive/88.ts?token=signed\"}}";else if(q.contains("action=get_vod_info"))result="{\"info\":{\"plot\":\"A real plot\",\"genre\":\"Drama\",\"cast\":\"Actor\",\"director\":\"Director\",\"releasedate\":\"2024\",\"duration\":\"01:20:00\"}}";else result="{\"user_info\":{\"auth\":1,\"status\":\"Active\"},\"server_info\":{\"timezone\":\"UTC\"}}";}catch(Exception ex){throw new java.io.IOException(ex);}byte[] b=result.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});}
 @After public void stop(){fixture.stop();}
 @Test public void xtreamGuideCatchupAndDetails()throws Exception{Provider p=new Provider(new JSONObject().put("mode","XTREAM").put("url",fixture.url).put("user","u").put("pass","p"));p.login();Provider.Item ch=new Provider.Item("42","Channel","7","","ts",false);ch.archive=true;ch.archiveDays=7;Programme programme=p.epg(ch,true).get(0);assertTrue(programme.archive);String link=p.catchup(ch,programme);assertTrue(link.contains("/timeshift/u/p/60/"));assertTrue(link.endsWith("/42.ts"));Provider.Item movie=p.details(new Provider.Item("4","Movie","8","","mp4",false),"vod");assertEquals("A real plot",movie.plot);assertEquals("Drama",movie.genre);assertEquals("2024",movie.year);assertEquals("Director",movie.director);}
 @Test public void macGuideUsesServerArchiveMarksAndProgramId()throws Exception{Provider p=new Provider(new JSONObject().put("mode","MAC").put("url",fixture.url+"/c").put("mac","00:1A:79:11:22:33"));p.login();Provider.Item ch=new Provider.Item("42","Channel","7","ffmpeg http://localhost/ch/42","",false);ch.archive=true;Programme programme=p.epg(ch,true,"2026-11-14").get(0);assertTrue(programme.archive);assertEquals("https://cdn.example.test/archive/88.ts?token=signed",p.catchup(ch,programme));assertTrue(queries.stream().anyMatch(q->q.contains("type=epg")&&q.contains("date=2026-11-14")));assertTrue(queries.stream().anyMatch(q->q.contains("type=tv_archive")&&q.contains("88.mpg")));}
}
